function allInputs(root, results=[]) {
  root.querySelectorAll('*').forEach(el => {
    if (el.tagName === 'INPUT' && el.type === 'file') results.push(el);
    if (el.shadowRoot) allInputs(el.shadowRoot, results);
  });
  return results;
}
const inputs = allInputs(document);
JSON.stringify({count: inputs.length, frames: window.frames.length, details: inputs.map(i => ({files: Array.from(i.files).map(f=>f.name)}))});

(function() {
  function allInputs(root, results) {
    results = results || [];
    root.querySelectorAll('*').forEach(function(el) {
      if (el.tagName === 'INPUT' && el.type === 'file') results.push(el);
      if (el.shadowRoot) allInputs(el.shadowRoot, results);
    });
    return results;
  }
  var found = allInputs(document);
  return JSON.stringify({count: found.length, frames: window.frames.length, details: found.map(function(i){ return {files: Array.from(i.files).map(function(f){return f.name;})}; })});
})()

(function() {
  var b64 = "YXBwcm92ZWQgdXBsb2FkIGZvciBOb3J0aHN0YXIgT3BzCg==";
  var byteChars = atob(b64);
  var byteNumbers = new Array(byteChars.length);
  for (var i = 0; i < byteChars.length; i++) byteNumbers[i] = byteChars.charCodeAt(i);
  var byteArray = new Uint8Array(byteNumbers);
  var file = new File([byteArray], "approved-upload.txt", {type: "text/plain"});
  var dt = new DataTransfer();
  dt.items.add(file);
  var input = document.querySelector('input[type="file"]');
  input.files = dt.files;
  input.dispatchEvent(new Event('input', {bubbles: true}));
  input.dispatchEvent(new Event('change', {bubbles: true}));
  return input.files.length + ':' + (input.files[0] ? input.files[0].name : 'none');
})()
